  },
  "claim_etabli": {
    "source_id": "pmid:1331788",
    "citation_verbatim": "the number of hip fractures was 43 percent lower (P = 0.043) and the total number of nonvertebral fractures was 32 percent lower (P = 0.015) among the women treated with vitamin D3 and calcium than among those who received placebo"
  },
  "requete_adverse": "vitamin D supplementation older adults no benefit",
  "citation_verbatim": "Daily supplemental vitamin D3 vs placebo did not decrease fall risk in generally healthy adults not selected for vitamin D insufficiency.",
  "source_id": "pmid:32492153",
